import type { Role } from '../app'
import type { FullSchema, Record as DbRecord, TableName } from '../db'

/**
 * Keys of a table's schema whose column renders as a Choice dropdown on the platform — the fields
 * `state_field` actually offers (`STTRMModelSNC.getStateFieldChoices` only includes fields where
 * `isChoiceTable()` is true, which corresponds to `dropdown: 'dropdown_with_none'` or
 * `'dropdown_without_none'`). `'suggestion'` (free-text autocomplete, e.g. `short_description`)
 * and `'none'` don't qualify, and `choices` alone isn't enough — many built-in Choice fields (e.g.
 * `state`, `priority`, `approval`) set `dropdown` without declaring `choices` inline, since their
 * `sys_choice` rows already exist on the platform. No system column ever qualifies.
 */
type ChoiceFieldKeys<T extends TableName> = {
    [K in keyof FullSchema<T>]: FullSchema<T>[K] extends { dropdown: 'dropdown_with_none' | 'dropdown_without_none' }
        ? K
        : never
}[keyof FullSchema<T>]

/**
 * Out-of-box condition-type templates (`sttrm_condition_type`) — the values shown in the platform's
 * "Requires" dropdown on a transition condition. Pass one of these names as `conditionType`, or pass
 * a custom `sttrm_condition_type` sys_id string for an instance-specific type.
 *
 * Names are case-sensitive — they match the OOB `sttrm_condition_type.name` field exactly.
 *
 * Note: `'Authorized'`, `'Not On hold'`, and `'Risk evaluation'` are `chg_model_condition_type`
 * subclass records. They resolve as FK references from any model table, but their evaluation
 * semantics apply only to `change_request` workflows.
 */
export type StateModelConditionType =
    | 'Transition Condition'
    | 'Transition Script'
    | 'Authorized'
    | 'Mandatory Fields'
    | 'Not On hold'
    | 'Risk evaluation'
    | 'Task has been through Approval'
    | 'Task is Approved'
    | 'Task is Rejected'

/** Out-of-box per-state attribute templates (`sttrm_attribute`). */
export type StateAttributeName = 'allowImplementation' | 'allowCiModification'

/**
 * A per-state attribute link (`sttrm_state_attribute`) — associates a state with an `sttrm_attribute`.
 * `$id` is required: the platform allows more than one link between the same state and attribute
 * (tracked as separate records), so identity can never be safely derived from `attribute` alone.
 */
type StateAttribute = Now.Internal.WithID<{
    /** OOB attribute name (e.g. `'allowImplementation'`) or a custom `sttrm_attribute` sys_id. */
    attribute: StateAttributeName | (string & {})
    /** Whether the attribute link is active. Defaults to true. */
    active?: boolean
}>

/**
 * A single state within a State Model (`sttrm_state`). The key used in the parent `states` map is a
 * developer-chosen identifier (e.g. `'new'`, `'assess'`) used to reference this state from a
 * transition's `from` / `to`. `$id` is required: the platform allows more than one state with the
 * same `value` on the same model (tracked as separate records), so identity can never be safely
 * derived from `value` alone.
 */
type State = Now.Internal.WithID<{
    /** Display label shown for the state on forms and in dropdowns. */
    label: string
    /** The value stored in the model's state field for this state (e.g. `'-5'`, `3`). */
    value: string | number
    /** Display order of the state in dropdowns. Lower numbers appear first. Defaults to 0. */
    sequence?: number
    /** Marks this state as the initial state assigned to new records. Defaults to false. */
    initial?: boolean
    /** Per-state attribute links (`sttrm_state_attribute`). */
    attributes?: StateAttribute[]
}>

/**
 * A field name referenced by a condition (`sttrm_transition_condition_field`). `$id` is required:
 * the platform allows more than one field row with the same name on the same condition (tracked as
 * separate records), so identity can never be safely derived from `name` alone.
 */
type ConditionField = Now.Internal.WithID<{
    /** Field name on the model's target table. */
    name: string
}>

/**
 * A gate on a transition (`sttrm_transition_condition`). Provide either an encoded query
 * (`condition`) or a server-side script (`conditionScript`) — not both. `$id` is required: a
 * condition's identity is never derived from `name`, since names are display/info text that can
 * change without that change representing a new condition.
 */
type TransitionCondition = Now.Internal.WithID<{
    /** Name of the condition, shown in transition-blocked error messages. */
    name: string
    /**
     * Encoded query string evaluated against the record. The transition is allowed only when the
     * query matches. Mutually exclusive with `conditionScript`.
     */
    condition?: string
    /**
     * Server-side script that returns a boolean (`true` = allow the transition, `false` = block it).
     * Use `Now.include('./script.js')` to keep the script in a separate file. The script receives the
     * `current` GlideRecord. Mutually exclusive with `condition`. Do not use `gs.addErrorMessage` —
     * conditions run across REST, Flow, and UI channels.
     */
    conditionScript?: string
    /**
     * The condition-type template shown in the platform's "Requires" dropdown. Pass an out-of-box
     * type name (e.g. `'Transition Script'`, `'Authorized'`) or a custom `sttrm_condition_type` sys_id.
     * When omitted, the condition has no required type ("-- None --").
     */
    conditionType?: StateModelConditionType | (string & {})
    /** Whether the condition is active. Defaults to true. */
    active?: boolean
    /** Evaluation order when a transition has multiple conditions. Lower numbers run first. Defaults to 100. */
    order?: number
    /** Description of what this condition validates. */
    description?: string
    /**
     * Field names on the model's target table that this condition references — written verbatim as
     * `sttrm_transition_condition_field` rows (one per name). Not validated by the SDK or by the
     * platform against the target table's columns. Use with type-based conditions such as
     * `'Mandatory Fields'` to list the required fields.
     */
    fields?: ConditionField[]
}>

/**
 * A valid move between two states (`sttrm_state_transition`). `from` and `to` reference keys defined
 * in the model's `states` map. `$id` is required: the platform allows more than one transition between
 * the same two states (e.g. one automatic, one manual, tracked as separate records), so identity can
 * never be safely derived from `from`/`to` alone.
 */
type Transition = Now.Internal.WithID<{
    /** Source state key — must be a key in the model's `states` map. */
    from: string
    /** Target state key — must be a key in the model's `states` map. */
    to: string
    /** Whether the transition occurs automatically once its conditions are met. Defaults to false. */
    automatic?: boolean
    /** Conditions that gate this transition. All active conditions must pass for the move to be allowed. */
    conditions?: TransitionCondition[]
}>

/**
 * Configuration for a State Model and all of its states, transitions, and conditions.
 *
 * The model is written to the table that matches the target `table`: `change_request` → `chg_model`,
 * `problem` → `prb_model`, `problem_task` → `prb_task_model`, any other table → the base
 * `sttrm_model`. Class-specific properties (`availableInUI`, `recordPreset`) only apply to
 * `change_request`; `defaultModel` and `description` apply to the subclass tables.
 *
 * @interface
 */
export type StateModel<T extends TableName> = Now.Internal.WithIdAndMetadata<{
    /** Name of the state model (e.g. "Normal", "Emergency"). */
    name: string
    /** The table the model applies to. Determines which model table the records are written to. */
    table: T
    /** The field on the table that holds the state value. Defaults to `'state'`. */
    stateField?: ChoiceFieldKeys<T> | (string & {})
    /** Whether the model is active. Defaults to true. */
    active?: boolean
    /**
     * Enables User Criteria-based access control (`availableFor`/`writableFor`/`notAvailableFor`) on
     * the model, in addition to `readRoles`/`writeRoles`. Defaults to false.
     */
    advancedSecurity?: boolean
    /** Roles allowed to read records using this model. Pass `Role` references or role names. */
    readRoles?: (Role | string)[]
    /** Roles allowed to write records using this model. Pass `Role` references or role names. */
    writeRoles?: (Role | string)[]
    /**
     * User Criteria that grant read access to records using this model, in addition to `readRoles`.
     * Only takes effect when `advancedSecurity` is enabled. Pass a `user_criteria` sys_id or a
     * `Record<'user_criteria'>` reference.
     */
    availableFor?: (string | DbRecord<'user_criteria'>)[]
    /**
     * User Criteria that grant write access to records using this model, in addition to `writeRoles`.
     * Only takes effect when `advancedSecurity` is enabled. Pass a `user_criteria` sys_id or a
     * `Record<'user_criteria'>` reference.
     */
    writableFor?: (string | DbRecord<'user_criteria'>)[]
    /**
     * User Criteria explicitly excluded from this model, overriding `availableFor`/`writableFor` and
     * any matching roles. Only takes effect when `advancedSecurity` is enabled. Pass a `user_criteria`
     * sys_id or a `Record<'user_criteria'>` reference.
     */
    notAvailableFor?: (string | DbRecord<'user_criteria'>)[]
    /**
     * Controls who may propose new Templates (`sttrm_template` records) for this model: `'read'`
     * allows anyone with read access to the model, `'write'` restricts proposal to those with write
     * access. Applies to all model tables, independently of `advancedSecurity`.
     */
    templateProposalAccess?: 'read' | 'write'
    /**
     * Users who can approve a proposed Template before it is published. Pass a `sys_user` sys_id or
     * a `Record<'sys_user'>` reference.
     */
    templateApprovalUsers?: (string | DbRecord<'sys_user'>)[]
    /**
     * Groups whose members can approve a proposed Template before it is published. Pass a
     * `sys_user_group` sys_id or a `Record<'sys_user_group'>` reference.
     */
    templateApprovalGroups?: (string | DbRecord<'sys_user_group'>)[]
    /**
     * Whether the model appears in UI dropdowns. Applies to `change_request` (chg_model) only — set
     * to `false` for system-assigned models. Defaults to true.
     */
    availableInUI?: boolean
    /**
     * Marks this as the default model for the table. Maps to the class-specific default flag
     * (`default_change_model` / `default_prb_model` / `default_prb_task_model`). Only one model per
     * table should set this. Defaults to false.
     */
    defaultModel?: boolean
    /** Description of the model. Stored only on the subclass tables (chg_model / prb_model / prb_task_model). */
    description?: string
    /**
     * Problem task type. Applies to `problem_task` (`prb_task_model`) only. Controls which kinds of
     * tasks the model governs: `'general'` for standard tasks, `'rca'` for root-cause-analysis tasks,
     * or `'model'` for template tasks.
     */
    taskType?: 'general' | 'rca' | 'model'
    /**
     * Template values applied when the model is assigned to a record. Applies to `change_request`
     * (chg_model) only. When set, the plugin automatically enables `apply_record_preset` so the
     * platform applies the preset on model assignment.
     */
    recordPreset?: string
    /**
     * Background color for this model, shown in Change calendar/board views (e.g. `'green'` or a hex
     * value like `'#2E7D32'`). Applies to `change_request` (chg_model) only.
     */
    color?: string
    /** ITIL change process classification. Applies to `change_request` (chg_model) only. */
    itilChangeProcess?: 'standard' | 'normal' | 'emergency'
    /** Map of developer-chosen state keys to state configurations. Keys are referenced by transitions. */
    states?: Record<string, State>
    /** Valid transitions between states, with optional gating conditions. Omit for a model-only update. */
    transitions?: Transition[]
}>

/**
 * Creates a State Model that defines states, transitions, and gating conditions for a table.
 * The plugin auto-detects the model table (`chg_model` / `prb_model` / `prb_task_model` / `sttrm_model`)
 * from the target `table`.
 *
 * @see https://docs.servicenow.com/csh?topicname=state-model.html&version=latest
 *
 * @param config - an object containing api properties
 */
export function StateModel<const T extends TableName>(config: StateModel<T>): StateModel<T> {
    return config
}
